const fs = require('fs');
const dir = '/files/tg-inbox';
fs.mkdirSync(dir, { recursive: true });
const results = [];
for (const it of $input.all()) {
  const u = it.json || {};
  const msg = u.message || {};
  const dateSec = Number(msg.date) || Math.floor(Date.now() / 1000);
  const cmd = {
    update_id: u.update_id,
    chat_id: msg.chat && msg.chat.id,
    from_id: msg.from && msg.from.id,
    text: (msg.text || ''),
    ts: new Date(dateSec * 1000).toISOString()
  };
  const base = 'cmd-' + String(cmd.update_id).replace(/[^0-9]/g, '') + '.json';
  const finalPath = dir + '/' + base;
  const tmpPath = finalPath + '.tmp';
  fs.writeFileSync(tmpPath, JSON.stringify(cmd, null, 2), 'utf-8');
  fs.renameSync(tmpPath, finalPath);
  results.push({ json: Object.assign({}, cmd, { written: finalPath }) });
}
return results;
